INSERT IGNORE INTO `pages` (`id`, `name`, `content`, `content_mode`, `custom_html`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES (23,'Trang chủ mới','<shortcode>[simple-slider key=\"TRANG BÌA\"][/simple-slider]</shortcode><shortcode>[booking-strip title=\"Đặt phòng trực tiếp tại Malibu\" button_label=\"Xem giá phòng\" promo_enabled=\"1\" trust_items=\"Giá tốt nhất khi đặt trực tiếp; Miễn phí huỷ theo chính sách; Lễ tân hỗ trợ 24/7\"][/booking-strip]</shortcode><shortcode>[about-us subtitle=\"The Malibu Hotel\" title=\"Live Beautifully – Sống trọn từng khoảnh khắc\" description=\"The Malibu Hotel toạ lạc tại 263 Lê Hồng Phong, ngay trung tâm thành phố biển Vũng Tàu. Đi vào hoạt động từ tháng 4/2016, khách sạn là toà nhà 23 tầng gồm 2 tầng hầm và 6 tầng dịch vụ, với tổng cộng 197 phòng nghỉ. Kiến trúc lấy cảm hứng từ châu Âu sang trọng và hiện đại; tất cả phòng đều có tầm nhìn hướng ra đại dương và ôm trọn một phần thành phố Vũng Tàu.\" highlights=\"197 phòng nghỉ hướng biển ; Toà nhà 23 tầng, 6 tầng dịch vụ ; Lễ tân và an ninh phục vụ 24/7\" style=\"style-1\" top_left_image=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc1/M-POOL-MALIBU-HOTEL-160.jpg\"][/about-us]</shortcode><shortcode>[panorama-tour subtitle=\"Tham quan 360°\" title=\"Bước vào Malibu trước khi bạn đến\" description=\"Sảnh đón, hồ bơi M Pool, phòng nghỉ hướng biển và sảnh hội nghị — xoay, phóng to và đi lại trong từng khu vực ngay trên trình duyệt, trước khi quyết định hạng phòng.\" poster_image=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc5/M-POOL-MALIBU-HOTEL-36.jpg\" tour_url=\"https://malibuhotel.vt360.vn/\" button_label=\"Khám phá không gian 360°\"][/panorama-tour]</shortcode><shortcode>[featured-rooms style=\"editorial\" subtitle=\"Các hạng phòng\" title=\"Phòng nghỉ &amp; Suite tại Malibu\" description=\"197 phòng nghỉ trải trên 4 hạng Premier, Diamond, Suite và President – từ phòng 40 m² hướng thành phố và biển đến Presidential Suite 250 m² với tầm nhìn toàn cảnh Vũng Tàu.\" room_ids=\"2,5,6,7,8,10\" button_label=\"Xem tất cả hạng phòng\" button_url=\"/rooms\"][/featured-rooms]</shortcode><shortcode>[recently-viewed subtitle=\"Tiếp tục nơi bạn dừng lại\" title=\"Phòng bạn vừa xem\"][/recently-viewed]</shortcode><shortcode>[highlight-columns subtitle=\"Ẩm thực\" title=\"Ba không gian, ba nhịp thưởng thức\" description=\"Từ buffet sáng nhìn ra Bãi Sau tới ly cà phê giữa buổi chiều, bữa ăn ở Malibu được xếp theo nhịp trong ngày của bạn.\" columns=\"3\" quantity=\"3\" image_1=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc3/M-POOL-MALIBU-HOTEL-60.jpg\" eyebrow_1=\"Buffet sáng\" title_1=\"Vela Restaurant\" description_1=\"Buffet sáng với món Việt và món Âu, phục vụ mỗi ngày trong không gian mở nhìn ra biển.\" link_label_1=\"Tìm hiểu thêm\" link_url_1=\"/services/vela-restaurant\" image_2=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc3/M-POOL-MALIBU-HOTEL-70.jpg\" eyebrow_2=\"Á Âu\" title_2=\"Carina Restaurant\" description_2=\"Thực đơn Á Âu gọi món, hải sản tươi theo mùa và các set tiệc riêng cho nhóm nhỏ.\" link_label_2=\"Tìm hiểu thêm\" link_url_2=\"/services/carina-restaurant\" image_3=\"https://malibuhotel.com.vn/files/blog/46_1815/Anh_1_4_1.jpg\" eyebrow_3=\"Cà phê &amp; trà\" title_3=\"The Lux Café\" description_3=\"Cà phê, trà và bánh ngọt cả ngày — chỗ ngồi làm việc hoặc hẹn gặp ngay tầng trệt.\" link_label_3=\"Tìm hiểu thêm\" link_url_3=\"/services/the-lux-cafe\"][/highlight-columns]</shortcode><shortcode>[feature-area subtitle=\"Hội nghị &amp; Sự kiện\" title=\"7 phòng hội nghị, sức chứa tới 450 khách\" description=\"Phòng Malibu Grand có thể ngăn thành 3 phòng nhỏ 120 khách mỗi phòng. Âm thanh chuẩn quốc tế, màn hình LED và máy chiếu hiện đại, nội thất cao cấp, cùng đội ngũ hỗ trợ kỹ thuật chuyên nghiệp và các gói tiệc linh hoạt.\" image=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc4/z7304583041023_6639f72ca0fe6cc33e22cbd47eedd674.jpg\" button_primary_label=\"Tìm hiểu thêm\" button_primary_url=\"/hoi-nghi-su-kien\"][/feature-area]</shortcode><shortcode>[offers subtitle=\"Ưu đãi\" title=\"Gói nghỉ dưỡng đang mở\" description=\"Các gói lưu trú chỉ áp dụng khi đặt trực tiếp, cập nhật theo mùa.\" category_id=\"1\" limit=\"3\" item_label=\"Xem ưu đãi\" button_label=\"Tất cả ưu đãi\" button_url=\"/tin-tuc\"][/offers]</shortcode><shortcode>[signature-experiences subtitle=\"Bản sắc Malibu\" title=\"Bốn điều làm nên Malibu\" description=\"Không phải danh sách tiện nghi, mà là những gì bạn chỉ gặp ở đây.\" background_image=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc1/MALIBU-HOTEL1.jpg\" quantity=\"4\" title_1=\"Không có phòng nào quay lưng ra biển\" description_1=\"197 phòng trên 23 tầng, mọi hạng phòng đều mở rèm ra Bãi Sau và một phần thành phố Vũng Tàu.\" image_1=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc2/DSC05931-HDR.jpg\" title_2=\"Sáu tầng dịch vụ trong cùng một toà nhà\" description_2=\"M Pool, M Spa, M Gym, hai nhà hàng, café, khu trẻ em và khu giải trí — không cần rời khách sạn.\" image_2=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc5/M-POOL-MALIBU-HOTEL-26.jpg\" title_3=\"Sảnh hội nghị lớn nhất khu trung tâm\" description_3=\"7 phòng họp linh hoạt tới 450 khách, ngay giữa thành phố và cách Bãi Sau vài phút đi bộ.\" image_3=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc4/M-POOL-MALIBU-HOTEL-86.jpg\" title_4=\"Lễ tân và an ninh trực 24/7\" description_4=\"Nhận phòng muộn, hỗ trợ hành lý, gọi xe hay đặt bàn — luôn có người trực, mọi giờ trong ngày.\" image_4=\"https://malibuhotel.com.vn/files/sites/site_70/site_70_gallery_muc1/M-POOL-MALIBU-HOTEL-159.jpg\"][/signature-experiences]</shortcode><shortcode>[galleries subtitle=\"Thư viện ảnh\" title=\"Malibu qua ống kính\" description=\"Toàn cảnh khách sạn, phòng nghỉ, nhà hàng, hồ bơi và không gian hội nghị.\" limit=\"6\"][/galleries]</shortcode><shortcode>[location-map subtitle=\"Vị trí\" title=\"Ở trung tâm, mở ra mặt biển\" map_embed_url=\"https://www.google.com/maps?q=The+Malibu+Hotel+263+Le+Hong+Phong+Vung+Tau&amp;output=embed\" directions_url=\"https://www.google.com/maps/dir/?api=1&amp;destination=The+Malibu+Hotel+263+Le+Hong+Phong+Vung+Tau\" button_label=\"Chỉ đường tới khách sạn\" places_title=\"Vài phút từ khách sạn\" place_ids=\"1,2,3,4,5,6\"][/location-map]</shortcode><shortcode>[newsletter subtitle=\"Bản tin Malibu\" title=\"Nhận ưu đãi trước khi mở bán rộng rãi\" description=\"Mỗi tháng một email: gói lưu trú mới, lịch sự kiện và ưu đãi chỉ dành cho người đăng ký.\" background_color=\"#16192c\"][/newsletter]</shortcode>',NULL,NULL,1,NULL,'home','Bản thiết kế lại trang chủ Malibu — xem trước trước khi thay trang chủ hiện tại.','published','2026-09-04 09:13:01','2026-09-04 09:50:55');
